                        match &args[0].value.kind {
                            ExprKind::Lit(Literal::Int(-2147483648)) => {
                                *expr = Expression::int(-2147483648);
                                return;
                            }
                            ExprKind::Lit(Literal::BigInt(n)) if *n == i64::MIN => {
                                *expr = Expression::new(ExprKind::Lit(Literal::BigInt(i64::MIN)));
                                return;
                            }
                            _ => {}
                        }
