                    "Array"
                        | "IntArray"
                        | "LongArray"
                        | "DoubleArray"
                        | "FloatArray"
                        | "CharArray"
                        | "BooleanArray"
                        | "ByteArray"
                        | "ShortArray"
                        | "UIntArray"
                        | "UByteArray"
                        | "UShortArray"
                        | "ULongArray"
